"""CSV and table output formatting (contract: Output formats)."""
from __future__ import annotations

from typing import Optional

from .result import Result

_NUMERIC = ("INTEGER", "REAL")


def value_text(v, type_: str) -> Optional[str]:
    """Text of a value, chosen by its Python type; None for NULL. `type_` is informational."""
    if v is None:
        return None
    if isinstance(v, float):
        return repr(v)
    if isinstance(v, int):
        return str(v)
    return v


def _csv_field(text: Optional[str]) -> str:
    if text is None:
        return ""
    if (
        text == ""
        or any(c in text for c in ',"\n\r')
        or text.startswith(" ")
        or text.endswith(" ")
    ):
        return '"' + text.replace('"', '""') + '"'
    return text


def format_csv(result: Result) -> str:
    lines = [",".join(_csv_field(name) for name in result.columns)]
    for row in result.rows:
        lines.append(
            ",".join(_csv_field(value_text(v, t)) for v, t in zip(row, result.types))
        )
    return "".join(line + "\n" for line in lines)


def _escape(text: str) -> str:
    return text.replace("\n", "\\n").replace("\r", "\\r")


def format_table(result: Result) -> str:
    headers = [_escape(name) for name in result.columns]
    body = []
    for row in result.rows:
        cells = []
        for v, t in zip(row, result.types):
            text = value_text(v, t)
            cells.append((_escape(text), t in _NUMERIC) if text is not None else ("NULL", False))
        body.append(cells)
    widths = [len(h) for h in headers]
    for cells in body:
        for i, (text, _) in enumerate(cells):
            widths[i] = max(widths[i], len(text))
    lines = [
        " | ".join(h.ljust(w) for h, w in zip(headers, widths)),
        "-+-".join("-" * w for w in widths),
    ]
    for cells in body:
        lines.append(
            " | ".join(
                text.rjust(w) if right else text.ljust(w)
                for (text, right), w in zip(cells, widths)
            )
        )
    n = len(result.rows)
    lines = [line.rstrip(" ") for line in lines]
    lines.append("(1 row)" if n == 1 else "(%d rows)" % n)
    return "".join(line + "\n" for line in lines)
